sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amount;
uniform float focusRadius;
uniform float feather;
uniform float gain;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float fr = length(d) / length(size * 0.5);
    float mask = smoothstep(focusRadius, focusRadius + feather, fr);
    float4 acc = float4(0.0);
    for (int i = 0; i < 24; i++) {
        float s = 1.0 - amount * mask * (float(i) / 23.0);
        acc += tex(ctr + d * s);
    }
    acc = acc / 24.0;
    acc = float4(acc.rgb * gain, acc.a);
    return fin(c, acc, opacity);
}
